-- Control-plane credentials and operational API metadata only. Never visitor data.
CREATE TABLE IF NOT EXISTS site_jev_credentials (site_id TEXT PRIMARY KEY REFERENCES admin_sites(id) ON DELETE CASCADE, mode TEXT NOT NULL CHECK(mode IN ('instance','site','disabled')), key_id TEXT, iv TEXT, ciphertext TEXT, revision TEXT NOT NULL, updated_at INTEGER NOT NULL, CHECK((mode='site' AND key_id IS NOT NULL AND iv IS NOT NULL AND ciphertext IS NOT NULL) OR (mode<>'site' AND key_id IS NULL AND iv IS NULL AND ciphertext IS NULL)));
CREATE TABLE IF NOT EXISTS site_jev_calls (id TEXT PRIMARY KEY, site_id TEXT NOT NULL REFERENCES admin_sites(id) ON DELETE CASCADE, started_at INTEGER NOT NULL, completed_at INTEGER, outcome TEXT NOT NULL CHECK(outcome IN ('started','success','http_error','timeout','network_error','invalid_response')), configured_model TEXT NOT NULL, actual_model TEXT, http_status INTEGER, elapsed_ms INTEGER, key_source TEXT NOT NULL CHECK(key_source IN ('instance','site')), credential_revision TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS site_jev_calls_site_time ON site_jev_calls(site_id,started_at DESC);
CREATE INDEX IF NOT EXISTS site_jev_calls_retention ON site_jev_calls(started_at);
